import crypto from 'crypto'

// Encrypt-only. The webapp (Vercel) only ever holds the PUBLIC key — it can lock
// credentials away but never read them back. Only the local Python worker holds
// the private key (CSR2_CRED_PUBLIC_KEY's pair, generated by scripts/csr2-gen-worker-keypair.js)
// and can decrypt. This is deliberate: even a full Supabase + Vercel env compromise
// doesn't expose plaintext passwords, since the decryption key never leaves the PC.
//
// Blob format (stored as-is in password_enc / twofa_code, both `text` columns):
//   { v: 1, ek: base64(RSA-OAEP-SHA256(aesKey)), iv: base64, tag: base64, ct: base64 }
// aesKey is a random 32-byte key used once per encryption (AES-256-GCM), itself
// sealed with RSA so only the private-key holder can recover it.

function getPublicKey() {
  const raw = process.env.CSR2_CRED_PUBLIC_KEY
  if (!raw) throw new Error('CSR2_CRED_PUBLIC_KEY is not configured')
  return raw.includes('\\n') ? raw.replace(/\\n/g, '\n') : raw
}

export function encryptForWorker(plaintext) {
  const publicKey = getPublicKey()
  const aesKey = crypto.randomBytes(32)
  const iv = crypto.randomBytes(12)
  const cipher = crypto.createCipheriv('aes-256-gcm', aesKey, iv)
  const ct = Buffer.concat([cipher.update(String(plaintext), 'utf8'), cipher.final()])
  const tag = cipher.getAuthTag()
  const ek = crypto.publicEncrypt(
    { key: publicKey, padding: crypto.constants.RSA_PKCS1_OAEP_PADDING, oaepHash: 'sha256' },
    aesKey
  )
  return JSON.stringify({
    v: 1,
    ek: ek.toString('base64'),
    iv: iv.toString('base64'),
    tag: tag.toString('base64'),
    ct: ct.toString('base64'),
  })
}
